const raw = String($json.message?.text || '').trim();
const chat_id = String($json.message?.chat?.id || '');
const user_id = String($json.message?.from?.id || $json.message?.chat?.id || '');
const parts = raw.split(/\s+/); const command = (parts.shift() || '').split('@')[0].toLowerCase();
const help = "Welcome to Telegram Intelligence Agent!

This bot monitors public Telegram channels and summarizes important posts.

Commands:

/add @channel
Add a public channel

/remove @channel
Stop monitoring a channel

/list
Show active channels

/latest @channel [hours] [min_views]
Show recent posts

/ask your question
Ask about collected posts

/digest
Get the latest 24-hour digest

/alert add keyword
Create a keyword alert

/alert list
Show your alerts

/alert remove ALERT_ID
Remove an alert";
const normalize = (v) => { const u=String(v||'').trim().replace(/^https?://t\.me/(?:s/)?/i,'').replace(/^@/,'').replace(//$/,'').toLowerCase(); return /^[a-z][a-z0-9_]{3,31}$/.test(u)?u:null; };
const reply = (text) => [{json:{chat_id,user_id,action:'reply',reply:text}}];
if (command === '/start') return reply(help);
if (command === '/help') return reply(help);
if (command === '/list') return parts.length?reply('Correct format: /list'):[{json:{chat_id,user_id,action:'list'}}];
if (command === '/digest') return parts.length?reply('Correct format: /digest'):[{json:{chat_id,user_id,action:'digest'}}];
if (command === '/add' || command === '/remove') { const channel=parts.length===1?normalize(parts[0]):null; return channel?[{json:{chat_id,user_id,action:command.slice(1),channel_username:channel}}]:reply('Invalid public channel username. Example: @telegram'); }
if (command === '/latest') { const channel=normalize(parts[0]); const hours=parts[1]===undefined?24:Number(parts[1]); const min_views=parts[2]===undefined?0:Number(parts[2]); if(parts.length<1||parts.length>3||!channel)return reply('Correct format: /latest @channel [hours] [min_views]'); if(!Number.isInteger(hours)||hours<1||hours>720)return reply('Hours must be an integer between 1 and 720.'); if(!Number.isInteger(min_views)||min_views<0)return reply('Minimum views must be a non-negative integer.'); return [{json:{chat_id,user_id,action:'latest',channel_username:channel,hours,min_views}}]; }
if (command === '/ask') { const question=parts.join(' ').trim(); return question.length>=3?[{json:{chat_id,user_id,action:'ask',question}}]:reply('Write a clear question after /ask.'); }
if (command === '/alert') { const sub=(parts.shift()||'').toLowerCase(); if(sub==='list'&&!parts.length)return [{json:{chat_id,user_id,action:'alert_list'}}]; if(sub==='add'){const keyword=parts.join(' ').trim();return keyword.length>=2&&keyword.length<=80?[{json:{chat_id,user_id,action:'alert_add',keyword}}]:reply('Correct format: /alert add keyword (2 to 80 characters)');} if(sub==='remove'&&parts.length===1&&/^[a-z0-9-]{6,64}$/i.test(parts[0]))return [{json:{chat_id,user_id,action:'alert_remove',alert_id:parts[0]}}]; return reply('Correct format: /alert add keyword | /alert list | /alert remove ALERT_ID'); }
return reply(help);

